import re, pathlib
root=pathlib.Path('/Users/alt/repos/mapctx')
for tasks_path in [root/'TASKS.md', root/'packages/sync-engine/TASKS.md', root/'example-tasks/TASKS.md']:
    text=tasks_path.read_text()
    entries={}
    for ch in text.split('### [')[1:]:
        tid=ch.split(']')[0]
        status=re.search(r'- status: (.+)',ch).group(1).strip()
        deps=re.search(r'- dependsOn: \[(.*)\]',ch)
        dep_list=[d.strip() for d in deps.group(1).split(',') if d.strip()] if deps else []
        start=re.search(r'- start: (.+)',ch).group(1).strip() if re.search(r'- start: (.+)',ch) else None
        completed=re.search(r'- completed: (.+)',ch).group(1).strip() if re.search(r'- completed: (.+)',ch) else None
        entries[tid]={'status':status,'deps':dep_list,'start':start,'completed':completed}
    print('\n'+str(tasks_path.relative_to(root)))
    for tid,e in entries.items():
        if e['status'] in {'doing','review','done'}:
            bad=[d for d in e['deps'] if d in entries and entries[d]['status']!='done']
            if bad:
                print(f'{tid}: active status {e["status"]} depends on non-done {bad}')
        if e['completed'] not in {'null',None} and e['start'] not in {'null',None} and e['completed']<e['start']:
            print(f'{tid}: completed before start ({e["start"]} -> {e["completed"]})')
